import{_ as r,C as o,o as i,c as s,a5 as l,E as c,j as a,a as t}from"./chunks/framework.BwlBv862.js";const g=JSON.parse('{"title":"Préparer la collaboration et l’accès des équipes","description":"","frontmatter":{"title":"Préparer la collaboration et l’accès des équipes","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"fr","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4a97f64b6bdc818ebb8d16eec1e67d95a2d0eae0b75f7cfd5c1493bf27244684","translationRevision":"35b1f76e8478df31e971460171b04483c310ea468e16ef13d508e6b858187d94","order":30},"headers":[],"relativePath":"fr/user/cloud/collaboration.md","filePath":"fr/user/cloud/collaboration.md","lastUpdated":1794611623000}'),u={name:"fr/user/cloud/collaboration.md"};function p(d,e,m,f,b,h){const n=o("DemoFrame");return i(),s("div",null,[e[0]||(e[0]=l('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">Préparer la collaboration et l’accès des équipes <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;Préparer la collaboration et l’accès des équipes {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objectif et prérequis {#goal-and-prerequisites}&quot;">​</a></h2><p>Accorder à un autre opérateur un rôle défini en conservant le contrôle du propriétaire. Il faut un hôte de bureau capable et un choix délibéré entre collaboration locale/native et Teams lié au compte. Teams nécessite aussi une <a href="./account.html">connexion Cloud</a> et un service déployé compatible. Commencez avec un accès en lecture seule et une configuration hors production.</p><h2 id="configure-owner-access" tabindex="-1">Configurer l’accès du propriétaire <a class="header-anchor" href="#configure-owner-access" aria-label="Permalink to &quot;Configurer l’accès du propriétaire {#configure-owner-access}&quot;">​</a></h2><ol><li>Ouvrez <strong>Settings → Collaboration</strong>. Examinez l’état de connexion et activez/configurez l’écouteur ou la passerelle voulus avec leurs commandes.</li><li>Examinez les origines autorisées et la matrice d’accès avant de créer une invitation. Choisissez uniquement les domaines, opérations et ressources nécessaires à l’opérateur.</li><li>Créez une invitation et transmettez son lien/jeton privé par un canal de confiance. Une invitation n’est pas une session active approuvée.</li><li>Examinez les demandes en attente et l’autorisation demandée. Approuvez uniquement l’opérateur attendu, puis confirmez son identité visible et sa connexion.</li><li>Utilisez l’inspecteur d’accès pour examiner les changements d’autorisation ultérieurs. Révoquez les invitations, identités ou sessions dont l’accès n’est plus nécessaire.</li></ol><p>Modifier une définition par délégation, adopter une définition en tant que propriétaire et approuver une exécution déléguée sont des décisions distinctes. Lisez la source enregistrée, les actions référencées et les permissions dans l’examen concerné. Un aperçu de définition seul n’autorise pas un effet.</p><h2 id="prepare-an-account-based-team" tabindex="-1">Préparer une équipe liée au compte <a class="header-anchor" href="#prepare-an-account-based-team" aria-label="Permalink to &quot;Préparer une équipe liée au compte {#prepare-an-account-based-team}&quot;">​</a></h2><p>Lorsque <strong>Settings → Teams</strong> est proposé, créez une équipe nommée et sélectionnez-la. Inscrivez <strong>this PC</strong> comme hôte avec un nom d’appareil reconnaissable, puis utilisez <strong>Start serving</strong> et examinez l’état de sa liaison. La création et l’inscription de l’hôte local sont raccordées dans l’interface ; elles sont distinctes de l’invitation d’un coéquipier. Un appareil contrôleur a son propre rôle d’inscription.</p><p>Choisissez un destinataire, un rôle et une durée d’invitation, puis examinez les demandes entrantes, membres et appareils. La recherche par pseudonyme nécessite un point de terminaison serveur déployé séparément et peut être indisponible sur le service actuel. Ne supposez pas qu’une recherche échouée signifie que la personne n’a pas de compte, et ne remplacez pas la sélection par un identifiant arbitraire.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Résultat attendu et état {#expected-result-and-status}&quot;">​</a></h2><p>Les commandes d’accès du propriétaire et la création/inscription des équipes dans l’interface existent. Le parcours complet de collaboration distante est expérimental : le fonctionnement LIVE réel entre deux ordinateurs, la recherche de pseudonymes en production, le comportement NAT/relais et tous les parcours de récupération des plateformes/effets ne sont pas établis ici. Une liaison prête ne prouve pas à elle seule l’application des permissions de bout en bout pour votre action.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Récupération {#recovery}&quot;">​</a></h2><p>Pour des autorisations ou révisions d’hôte obsolètes, rechargez et examinez à nouveau. Pour des commandes non confirmées, consultez le résultat enregistré avant de réessayer. Arrêtez le service ou révoquez l’accès en terminant une session. Excluez les jetons d’invitation et identifiants secrets des <a href="./../preferences/troubleshooting.html">rapports de diagnostic</a> publics.</p>',13)),c(n,{scenario:"collaboration",locale:"fr",title:"Démo : collaboration"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[t("Détails de fonctionnement "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Détails de fonctionnement {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,[t("Après jonction/approbation Teams, l’hôte confirme la révision native actuelle. "),a("code",null,"pendingHost"),t(" indique l’attente ; transport actif ou appartenance ne donnent pas seuls d’accès natif. Rechargez après changement de permission et vérifiez hôte/appareil. Observer privilégie lecture ; moderator ajoute certains contrôles, automationEditor certaines éditions, custom exige une politique explicite revue. Aucun ne donne scripts/effets illimités. Consultez "),a("a",{href:"./../../developer/collaboration.html#operational-details"},"rôles et confirmation"),t(" si les contrôles n’expliquent pas un refus.")],-1))])}const q=r(u,[["render",p]]);export{g as __pageData,q as default};
